import {seeds} from './catalog.js';
import {getJSON,plain,norm,safeURL,classify} from './providers.js';
export const sourceLabels={archive:'Internet Archive',commons:'Wikimedia Commons',rutube:'RUTUBE',peertube:'PeerTube',dailymotion:'Dailymotion',vk:'VK Видео',youtube:'YouTube',vimeo:'Vimeo'};
export const providers=Object.keys(sourceLabels);
export const linkProviders=['rutube','vk','youtube','vimeo','dailymotion'];
const params=o=>new URLSearchParams(o).toString();
const minimum=600;
export function isRelated(title,q,translated=''){if(!q)return true;const t=norm(title).normalize('NFKD').replace(/[\u0300-\u036f]/g,'');const variants=(/^(киберпанк|cyberpunk)$/i.test(q.trim())&&translated?[translated]:[q,translated]).filter(Boolean);return variants.some(v=>{const words=norm(v).split(/[^a-zа-я0-9]+/).filter(w=>w.length>2&&!['the','and','для','это','или','фильм','series','movie'].includes(w));return !words.length||words.every(w=>t.includes(w))})}
export function isExtra(title){return /trailer|teaser|review|recap|reaction|gameplay|walkthrough|stream|radio mix|techno|music|tutorial|librarian|on deck|framework desktop|touch controls|2077|прохождение|летсплей|стрим|радио|микс|обзор|трейлер|тизер|реакци|прохожден|дайджест|как (снимали|создавали)|cómo se hizo|making of|everything you need to know|\btop \d/i.test(title)}
function kindOf(title,description=''){const seed=seeds.find(x=>norm(title)===norm(x.original)||norm(title)===norm(x.title));if(seed)return seed.kind;return /edgerunners|бегущие по краю/i.test(title)?'animatedSeries':classify({title,subject:description})}
function matchFilter(item,{q,translated,fullOnly=true,kind}){return item&&isRelated(item.title,q,translated)&&(!fullOnly||!item.nonCinema)&&(!fullOnly||(!isExtra(item.title)&&(!item.duration||item.duration>=minimum)))&&(!kind||kind==='all'||item.kind===kind)}
export function fromRutube(d){const id=String(d?.id||d?.video_id||'');if(!/^[a-f0-9]{32}$/i.test(id)||d.is_paid||d.is_live||d.is_hidden)return null;const title=plain(d.title||d.name)||'Видео RUTUBE';return {id:'rt:'+id,ref:id,provider:'rutube',title,original:title,kind:kindOf(title,d.description),duration:Number(d.duration)||0,year:plain(d.title).match(/\b(?:19|20)\d{2}\b/)?.[0]||'',description:plain(d.description),creator:plain(d.author?.name||d.author?.username),poster:safeURL(d.thumbnail_url||d.picture_url,['rtbcdn.ru','rutube.ru']),source:'https://rutube.ru/video/'+id+'/',playback:'embed',embedUrl:'https://rutube.ru/play/embed/'+id+'/'}}
export async function searchRutube(a){const j=await getJSON('https://rutube.ru/api/search/video/?'+params({query:a.q||'фильмы',page:a.page||1,per_page:24}),a.signal,12000);const list=j.results||j.data?.results;if(!Array.isArray(list))throw new Error('Поиск RUTUBE недоступен. Используйте поиск на площадке ниже.');return {items:list.map(fromRutube).filter(x=>matchFilter(x,a)),more:!!j.has_next,page:a.page}}
export function fromPeerTube(d){if(d.nsfw||d.privacy?.id!==1||d.isLive)return null;const src=safeURL(d.url),embed=safeURL(d.embedUrl);if(!src||!embed)return null;const s=new URL(src),e=new URL(embed);if(s.origin!==e.origin||!/^\/videos\/embed\/[a-zA-Z0-9-]+\/?$/.test(e.pathname)||!publicHost(s.hostname))return null;const title=plain(d.name);return {id:'pt:'+s.host+':'+d.uuid,ref:d.uuid,provider:'peertube',title,original:title,kind:kindOf(title,d.category?.label),duration:Number(d.duration)||0,description:plain(d.description||d.truncatedDescription),creator:plain(d.channel?.displayName||d.account?.displayName),poster:safeURL(d.previewUrl||d.thumbnailUrl),source:src,playback:'embed',embedUrl:embed,sourceLicense:plain(d.licence?.label),language:plain(d.language?.label),nonCinema:d.category?.id!=null&&![2,4,9,10].includes(d.category.id)}}
export async function searchPeerTube(a){const term=(/edgerunners/i.test(a.translated||'')?'Edgerunners':a.translated)||a.q||({film:'full film',animation:'animation',series:'series',animatedSeries:'cartoon'}[a.kind]||'film');const j=await getJSON('https://sepiasearch.org/api/v1/search/videos?'+params({search:term,nsfw:'false',start:((a.page||1)-1)*20,count:20,durationMin:a.fullOnly?minimum:0}),a.signal,15000);return {items:(j.data||[]).map(fromPeerTube).filter(x=>matchFilter(x,a)),more:j.total>(a.page||1)*20,page:a.page}}
export function fromDailymotion(d){if(!/^[a-zA-Z0-9]+$/.test(d.id||'')||!d.allow_embed)return null;const title=plain(d.title);return {id:'dm:'+d.id,ref:d.id,provider:'dailymotion',title,original:title,kind:kindOf(title),duration:Number(d.duration)||0,description:'Публикация Dailymotion. Название, длительность и автор переданы площадкой; полнота фильма не проверена.',creator:plain(d['owner.screenname']),poster:safeURL(d.thumbnail_360_url,['dmcdn.net']),source:'https://www.dailymotion.com/video/'+d.id,playback:'dailymotion',nonCinema:['videogames','music','news','tech','sport','auto','school','people','animals','travel'].includes(d.channel)}}
export async function searchDailymotion(a){const terms=[...new Set([a.q,a.translated].filter(Boolean))];if(!terms.length)terms.push('full movie');const settled=await Promise.allSettled(terms.map(term=>getJSON('https://api.dailymotion.com/videos?'+params({search:term,fields:'id,title,thumbnail_360_url,duration,owner.screenname,allow_embed,channel',limit:24,page:a.page||1,longer_than:a.fullOnly?10:0,explicit:'false'}),a.signal,15000)));const good=settled.filter(r=>r.status==='fulfilled').map(r=>r.value);if(!good.length)throw settled[0].reason;const seen=new Set();return {items:good.flatMap(j=>j.list||[]).map(fromDailymotion).filter(x=>{if(!matchFilter(x,a)||seen.has(x.id))return false;seen.add(x.id);return true}),more:good.some(j=>j.has_more),page:a.page}}
function publicHost(host){return host.includes('.')&&!/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/.test(host)&&!host.endsWith('.local')&&!host.includes(':')&&!/^\d+(\.\d+){3}$/.test(host)}
function inputURL(input){const text=String(input).trim();const raw=/<iframe\b/i.test(text)?text.match(/\bsrc\s*=\s*["']([^"']+)["']/i)?.[1]:text;if(!raw)throw new Error('Не удалось найти ссылку на плеер в коде вставки.');let u;try{u=new URL(raw.replace(/&amp;/g,'&'))}catch{throw new Error('Вставьте полную ссылку https://… или код iframe.')}if(u.protocol!=='https:'||u.username||u.password||(u.port&&u.port!=='443')||u.searchParams.has('access_token'))throw new Error('Нужна публичная HTTPS-ссылка на видео без токенов авторизации.');return u}
export function parseVideoLink(input){const u=inputURL(input),host=u.hostname.toLowerCase().replace(/^www\./,'').replace(/^m\./,'');let item;const base={kind:'film',title:'Видео по ссылке',description:'Воспроизводится в официальном плеере площадки. Доступность и качество определяет источник.',duration:0,poster:'assets/cover.svg',playback:'embed'};
if(host==='rutube.ru'){const id=u.pathname.match(/^\/(?:video|play\/embed)\/([a-f0-9]{32})\/?$/i)?.[1];if(id)item={provider:'rutube',ref:id,source:'https://rutube.ru/video/'+id+'/',embedUrl:'https://rutube.ru/play/embed/'+id+'/'}}
if(['vk.com','vkvideo.ru','vk.ru'].includes(host)){let owner,id,hash;const path=u.pathname.match(/^\/video(-?\d+)_(\d+)\/?$/);if(path){[,owner,id]=path}else if(u.pathname==='/video_ext.php'){owner=u.searchParams.get('oid');id=u.searchParams.get('id');hash=u.searchParams.get('hash')}if(/^-?\d+$/.test(owner||'')&&/^\d+$/.test(id||'')&&(!hash||/^[a-zA-Z0-9_-]{1,128}$/.test(hash)))item={provider:'vk',ref:owner+'_'+id,source:'https://vkvideo.ru/video'+owner+'_'+id,embedUrl:'https://vkvideo.ru/video_ext.php?'+params({oid:owner,id,hd:2,...(hash?{hash}:{})})}}
if(['youtube.com','youtube-nocookie.com','youtu.be'].includes(host)){const id=host==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.match(/^\/(?:embed|shorts)\/([^/]+)/)?.[1];if(/^[a-zA-Z0-9_-]{11}$/.test(id||''))item={provider:'youtube',ref:id,source:'https://www.youtube.com/watch?v='+id,embedUrl:'https://www.youtube-nocookie.com/embed/'+id+'?playsinline=1',poster:'https://i.ytimg.com/vi/'+id+'/hqdefault.jpg'}}
if(['vimeo.com','player.vimeo.com'].includes(host)){const id=u.pathname.match(/^\/(?:video\/)?(\d+)\/?$/)?.[1],h=u.searchParams.get('h');if(id&&(!h||/^[a-zA-Z0-9]+$/.test(h)))item={provider:'vimeo',ref:id,source:'https://vimeo.com/'+id,embedUrl:'https://player.vimeo.com/video/'+id+(h?'?h='+h:'')}}
if(['dailymotion.com','dai.ly','geo.dailymotion.com'].includes(host)){const id=host==='dai.ly'?u.pathname.slice(1):host==='geo.dailymotion.com'?u.searchParams.get('video'):u.pathname.match(/^\/(?:embed\/)?video\/([a-zA-Z0-9]+)/)?.[1];if(/^[a-zA-Z0-9]+$/.test(id||'')){const player=u.pathname.match(/^\/player\/([a-zA-Z0-9]+)\.html$/)?.[1];item={provider:'dailymotion',ref:id,playback:player?'embed':'dailymotion',source:'https://www.dailymotion.com/video/'+id,...(player?{embedUrl:'https://geo.dailymotion.com/player/'+player+'.html?video='+id}:{})}}}
if(!item&&publicHost(host)&&/^\/videos\/(watch|embed)\/[a-zA-Z0-9-]+\/?$/.test(u.pathname)){const id=u.pathname.split('/').filter(Boolean)[2];item={provider:'peertube',ref:id,source:u.origin+'/videos/watch/'+id,embedUrl:u.origin+'/videos/embed/'+id}}
if(!item)throw new Error('Поддерживаются ссылки RUTUBE, VK Видео, YouTube, Vimeo, Dailymotion и PeerTube. Для других сайтов требуется отдельная проверка интеграции.');return {...base,...item,id:(item.provider==='rutube'?'rt:':item.provider==='dailymotion'?'dm:':item.provider+':')+item.ref,title:'Видео '+sourceLabels[item.provider]};}
export function validEmbed(item){try{const parsed=parseVideoLink(item.embedUrl||item.source);return parsed.provider===item.provider&&parsed.playback==='embed'?parsed.embedUrl+(parsed.provider==='peertube'?'?p2p=0':''):''}catch{return ''}}
export function resolveEmbedded(item,playerID=''){let embedUrl=item.embedUrl;if(item.provider==='dailymotion'&&!embedUrl&&/^[a-zA-Z0-9]{3,30}$/.test(playerID))embedUrl='https://geo.dailymotion.com/player/'+playerID+'.html?video='+item.ref;const safe=validEmbed({...item,embedUrl});return {playback:safe?'embed':'external',embedUrl:safe,source:item.source,creator:item.creator||sourceLabels[item.provider],language:item.language||'Язык и субтитры — в плеере источника',providerLabel:sourceLabels[item.provider],sourceLicense:item.sourceLicense,episodes:[],notice:item.provider==='dailymotion'&&!safe?'Для встроенного плеера Dailymotion нужен ваш Player ID из Dailymotion Studio. Пока видео можно открыть на самой площадке.':item.provider==='vk'?'Если VK не разрешает запуск по обычной ссылке, используйте «Поделиться → Код для вставки».':''}}
